from typing import List

def getMinOperations(change: List[int], arr: List[int]) -> int:
    n, m = len(change), len(arr)

    def ok(T: int) -> bool:
        # 只用前 T 次操作：每个元素在它最后一次出现的时刻置 NULL 最宽松
        last = {}
        for i in range(T):
            if change[i] > 0:
                last[change[i]] = i
        if len(last) < m:
            return False
        used = 0
        for j, t in sorted(last.items(), key=lambda kv: kv[1]):
            used += arr[j - 1] + 1      # arr[j] 次减 1 + 1 次置 NULL
            if used > t + 1:            # 必须都在第 t 次操作（含）之前完成
                return False
        return True

    if not ok(n):
        return -1
    lo, hi = 1, n
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo
